  "settings.schema.scheduler.retain_sessions.label": "保留会话",
  "settings.schema.scheduler.retain_sessions.desc":
    "每个任务 id 保留多少个已完成的调度器会话文件夹。",
  "settings.schema.system.prompts.label": "提示词模板",
  "settings.schema.system.prompts.dir.label": "提示词目录",
